import java.util.Locale;

/**
 * WL-SVM / PE-P1-svm-specA
 *
 * Soft-margin SVM trained by projected dual gradient ascent (Gauss-Seidel, in place),
 * on a deterministic dataset generated by the frozen Park-Miller LCG with an
 * Irwin-Hall(12) normal transform.
 *
 * Three logical modules, per spec 2.1: data, svm, app.
 * Standard library only; no linear-algebra / tensor / statistics / BLAS facility is used.
 */
public final class Main {

    // ==================================================================
    // module: data -- the LCG-PM generator and the dataset builder
    // ==================================================================
    static final class data {

        // ---- frozen constants (spec 2.2) ----
        static final int D = 4;
        static final int N_TRAIN_C1 = 100;
        static final int N_TRAIN_C2 = 100;
        static final int N_TEST_C1 = 50;
        static final int N_TEST_C2 = 50;
        static final double[] MU1 = { 1.0, 1.0, 0.5, -0.5 };
        static final double[] MU2 = { -1.0, -1.0, -0.5, 0.5 };
        static final double SIGMA = 0.8;
        static final int SEED = 1234567;

        // ---- LCG-PM ----
        static final long MULT = 48271L;
        static final long MOD = 2147483647L;

        private long state;

        data(long seed) {
            this.state = seed;
        }

        long nextState() {
            state = (MULT * state) % MOD;
            return state;
        }

        double nextUniform() {
            return (double) nextState() / 2147483647.0;
        }

        /** Irwin-Hall(12) - 6; accumulation ascending, not reassociated. */
        double nextNormal() {
            double t = 0.0;
            for (int k = 0; k < 12; k++) {
                t = t + nextUniform();
            }
            return t - 6.0;
        }

        /** One block: points ascending, dimensions ascending. */
        double[][] drawBlock(int n, double[] mu) {
            double[][] out = new double[n][D];
            for (int i = 0; i < n; i++) {
                for (int d = 0; d < D; d++) {
                    out[i][d] = mu[d] + SIGMA * nextNormal();
                }
            }
            return out;
        }

        static final class Dataset {
            double[][] xTrain;  // 200 x 4, class +1 first, class -1 second
            double[] yTrain;    // +1 for i < 100, -1 otherwise
            double[][] xTestC1; // 50 x 4
            double[][] xTestC2; // 50 x 4
        }

        /** Exact draw order of spec 2.3: one stream, four blocks, no reset. */
        static Dataset build() {
            data rng = new data(SEED);

            double[][] tr1 = rng.drawBlock(N_TRAIN_C1, MU1);
            double[][] tr2 = rng.drawBlock(N_TRAIN_C2, MU2);
            double[][] te1 = rng.drawBlock(N_TEST_C1, MU1);
            double[][] te2 = rng.drawBlock(N_TEST_C2, MU2);

            int n = N_TRAIN_C1 + N_TRAIN_C2;
            Dataset ds = new Dataset();
            ds.xTrain = new double[n][];
            ds.yTrain = new double[n];
            for (int i = 0; i < N_TRAIN_C1; i++) {
                ds.xTrain[i] = tr1[i];
                ds.yTrain[i] = 1.0;
            }
            for (int i = 0; i < N_TRAIN_C2; i++) {
                ds.xTrain[N_TRAIN_C1 + i] = tr2[i];
                ds.yTrain[N_TRAIN_C1 + i] = -1.0;
            }
            ds.xTestC1 = te1;
            ds.xTestC2 = te2;
            return ds;
        }
    }

    // ==================================================================
    // module: svm -- training, SV extraction, w/b recovery, f, g, evaluation
    // ==================================================================
    static final class svm {

        // ---- frozen constants (spec 2.2) ----
        static final double C = 10.0;
        static final double LR = 0.0001;
        static final double LIMIT = 0.0001;
        static final int SWEEPS = 1000;
        static final double EPS_SV = 0.0000001;

        final int n;
        final int dim;
        final double[][] x;
        final double[] y;

        double[][] G;
        double[] alpha;
        double beta;

        boolean judgeLast;
        double errorLast;
        double maxAbsDeltaLast;

        double[] w;
        double b;
        int nsMargin;
        int nsInside;

        svm(double[][] x, double[] y, int dim) {
            this.x = x;
            this.y = y;
            this.n = y.length;
            this.dim = dim;
        }

        /** Mandatory one-off Gram build (spec 2.4). */
        void buildGram() {
            G = new double[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    double s = 0.0;
                    for (int d = 0; d < dim; d++) {
                        s = s + x[i][d] * x[j][d];
                    }
                    G[i][j] = s;
                }
            }
        }

        /** Exactly SWEEPS sweeps, no early exit (spec 2.4). */
        void train() {
            buildGram();
            alpha = new double[n];
            for (int i = 0; i < n; i++) {
                alpha[i] = 0.0;
            }
            beta = 1.0;

            for (int sweep = 0; sweep < SWEEPS; sweep++) {

                boolean judge = false;
                double error = 0.0;
                double maxAbsDelta = 0.0;

                // (3.1) update alpha, ascending i, in place (Gauss-Seidel)
                for (int i = 0; i < n; i++) {
                    final double yi = y[i];
                    final double[] Gi = G[i];

                    double item1 = 0.0;
                    for (int j = 0; j < n; j++) {
                        item1 = item1 + alpha[j] * yi * y[j] * Gi[j];
                    }

                    double item2 = 0.0;
                    for (int j = 0; j < n; j++) {
                        item2 = item2 + alpha[j] * yi * y[j];
                    }

                    double delta = 1.0 - item1 - beta * item2;
                    double ad = Math.abs(delta);
                    if (ad > maxAbsDelta) {
                        maxAbsDelta = ad;
                    }

                    alpha[i] = alpha[i] + LR * delta;
                    if (alpha[i] < 0.0) {
                        alpha[i] = 0.0;
                    } else if (alpha[i] > C) {
                        alpha[i] = C;
                    } else if (ad > LIMIT) {
                        judge = true;
                        error = error + (ad - LIMIT);
                    }
                }

                // (3.2) update beta, once per sweep
                double s = 0.0;
                for (int i = 0; i < n; i++) {
                    s = s + alpha[i] * y[i];
                }
                beta = beta + s * s / 2.0;

                judgeLast = judge;
                errorLast = error;
                maxAbsDeltaLast = maxAbsDelta;
            }
        }

        /** Support-vector extraction and w/b recovery (spec 2.5). */
        void recover() {
            int[] sMargin = new int[n];
            int mCount = 0;
            int[] sInside = new int[n];
            int iCount = 0;
            for (int i = 0; i < n; i++) {
                if (EPS_SV < alpha[i] && alpha[i] < C - EPS_SV) {
                    sMargin[mCount++] = i;
                }
            }
            for (int i = 0; i < n; i++) {
                if (alpha[i] >= C - EPS_SV) {
                    sInside[iCount++] = i;
                }
            }
            nsMargin = mCount;
            nsInside = iCount;

            w = new double[dim];
            for (int d = 0; d < dim; d++) {
                w[d] = 0.0;
            }
            for (int d = 0; d < dim; d++) {
                for (int k = 0; k < mCount; k++) {
                    int i = sMargin[k];
                    w[d] = w[d] + alpha[i] * y[i] * x[i][d];
                }
                for (int k = 0; k < iCount; k++) {
                    int i = sInside[k];
                    w[d] = w[d] + alpha[i] * y[i] * x[i][d];
                }
            }

            if (mCount == 0) {
                System.err.println("FAIL: |S_margin| == 0");
                System.exit(1);
            }

            double acc = 0.0;
            for (int k = 0; k < mCount; k++) {
                int i = sMargin[k];
                double dp = 0.0;
                for (int d = 0; d < dim; d++) {
                    dp = dp + w[d] * x[i][d];
                }
                acc = acc + (y[i] - dp);
            }
            b = acc / (double) mCount;
        }

        double f(double[] p) {
            double s = 0.0;
            for (int d = 0; d < dim; d++) {
                s = s + w[d] * p[d];
            }
            return s + b;
        }

        int g(double[] p) {
            return f(p) >= 0.0 ? 1 : -1;
        }

        double objective() {
            double sum = 0.0;
            for (int i = 0; i < n; i++) {
                sum = sum + alpha[i];
            }
            double quad = 0.0;
            for (int i = 0; i < n; i++) {
                double inner = 0.0;
                for (int j = 0; j < n; j++) {
                    inner = inner + alpha[i] * alpha[j] * y[i] * y[j] * G[i][j];
                }
                quad = quad + inner;
            }
            return sum - 0.5 * quad;
        }

        double alphaSum() {
            double s = 0.0;
            for (int i = 0; i < n; i++) {
                s = s + alpha[i];
            }
            return s;
        }

        double alphaYSum() {
            double s = 0.0;
            for (int i = 0; i < n; i++) {
                s = s + alpha[i] * y[i];
            }
            return s;
        }

        double alphaChecksum() {
            double s = 0.0;
            for (int i = 0; i < n; i++) {
                s = s + alpha[i] * (double) ((i % 97) + 1);
            }
            return s;
        }
    }

    // ==================================================================
    // module: app -- entry point, output formatting
    // ==================================================================
    static final class app {

        static String stripNegZero(String s) {
            if (s.length() > 0 && s.charAt(0) == '-') {
                boolean allZero = true;
                for (int i = 1; i < s.length(); i++) {
                    char c = s.charAt(i);
                    if (c >= '1' && c <= '9') {
                        allZero = false;
                        break;
                    }
                }
                if (allZero) {
                    return s.substring(1);
                }
            }
            return s;
        }

        static String f6(double v) {
            double z = (v == 0.0) ? 0.0 : v;
            return stripNegZero(String.format(Locale.ROOT, "%.6f", z));
        }

        static String f12(double v) {
            double z = (v == 0.0) ? 0.0 : v;
            return stripNegZero(String.format(Locale.ROOT, "%.12f", z));
        }

        static void run() {
            data.Dataset ds = data.build();

            svm model = new svm(ds.xTrain, ds.yTrain, data.D);
            model.train();
            model.recover();

            // ---- evaluation ----
            int trainCorrect = 0;
            for (int i = 0; i < ds.yTrain.length; i++) {
                int pred = model.g(ds.xTrain[i]);
                int truth = ds.yTrain[i] >= 0.0 ? 1 : -1;
                if (pred == truth) {
                    trainCorrect++;
                }
            }
            double trainAcc = (double) trainCorrect / (double) ds.yTrain.length;

            int nTest = data.N_TEST_C1 + data.N_TEST_C2;
            int[] pred = new int[nTest];
            int correctC1 = 0;
            int correctC2 = 0;
            for (int i = 0; i < data.N_TEST_C1; i++) {
                int p = model.g(ds.xTestC1[i]);
                pred[i] = p;
                if (p == 1) {
                    correctC1++;
                }
            }
            for (int i = 0; i < data.N_TEST_C2; i++) {
                int p = model.g(ds.xTestC2[i]);
                pred[data.N_TEST_C1 + i] = p;
                if (p == -1) {
                    correctC2++;
                }
            }
            int totalCorrect = correctC1 + correctC2;
            double testAcc = (double) totalCorrect / (double) nTest;
            double testAccC1 = (double) correctC1 / (double) data.N_TEST_C1;
            double testAccC2 = (double) correctC2 / (double) data.N_TEST_C2;

            StringBuilder out = new StringBuilder(8192);
            out.append("SVM_VERSION 1\n");
            out.append("SWEEPS ").append(svm.SWEEPS).append('\n');
            out.append("CONVERGED ").append(model.judgeLast ? 0 : 1).append('\n');
            out.append("ERROR_LAST ").append(f6(model.errorLast)).append('\n');
            out.append("MAX_ABS_DELTA ").append(f6(model.maxAbsDeltaLast)).append('\n');
            out.append("BETA ").append(f6(model.beta)).append('\n');
            out.append("NS_MARGIN ").append(model.nsMargin).append('\n');
            out.append("NS_INSIDE ").append(model.nsInside).append('\n');
            out.append("W");
            for (int d = 0; d < data.D; d++) {
                out.append(' ').append(f6(model.w[d]));
            }
            out.append('\n');
            out.append("B ").append(f6(model.b)).append('\n');
            out.append("OBJECTIVE ").append(f6(model.objective())).append('\n');
            out.append("ALPHA_SUM ").append(f6(model.alphaSum())).append('\n');
            out.append("ALPHA_Y_SUM ").append(f12(model.alphaYSum())).append('\n');
            out.append("ALPHA_CHECKSUM ").append(f6(model.alphaChecksum())).append('\n');
            out.append("TRAIN_ACC ").append(f6(trainAcc)).append('\n');
            out.append("TEST_ACC ").append(f6(testAcc)).append('\n');
            out.append("TEST_ACC_C1 ").append(f6(testAccC1)).append('\n');
            out.append("TEST_ACC_C2 ").append(f6(testAccC2)).append('\n');
            out.append("TEST_CORRECT ").append(correctC1).append(' ')
               .append(correctC2).append(' ').append(totalCorrect).append('\n');
            out.append("PRED");
            for (int i = 0; i < nTest; i++) {
                out.append(' ').append(pred[i]);
            }
            out.append('\n');
            out.append("ALPHA");
            for (int i = 0; i < model.alpha.length; i++) {
                out.append(' ').append(f6(model.alpha[i]));
            }
            out.append('\n');

            System.out.print(out);
            System.out.flush();
        }
    }

    public static void main(String[] args) {
        app.run();
    }
}
